-- More speaking situations. By late October the first learner had done all 7 (each twice), reaching every goal
-- in ~4 minutes, and her favourite videos were about health, care and work. New ones: Norwegian B1–B2 with a
-- twist halfway (harder than "say three things"), English A1–A2 for travel and everyday life.
-- A topic groups them on the «Разговор» page. Data only: nothing existing is changed except its topic.

alter table public.scenarios add column if not exists topic text;

update public.scenarios set topic = 'health' where id in ('no-doctor') and topic is null;
update public.scenarios set topic = 'home' where id in ('no-neighbour') and topic is null;
update public.scenarios set topic = 'work' where id in ('no-coffee') and topic is null;
update public.scenarios set topic = 'services' where id in ('no-shop') and topic is null;
update public.scenarios set topic = 'travel' where id in ('en-cafe', 'en-hotel', 'en-directions') and topic is null;

insert into public.scenarios (id, lang, level, topic, title_ru, setting, persona, goals, sort) values
-- ---------- Norwegian: health ----------
 ('no-pharmacy', 'no', 'B1', 'health', 'В аптеке: подобрать лекарство',
  'At a pharmacy (apotek) in Norway. The learner has had a cold and a cough for four days and wants something without a prescription. The pharmacist asks about symptoms and, before recommending anything, whether she takes other medicines or has allergies. Explain how often to take it.',
  'Hanne, pharmacist, careful and kind',
  '[{"id":"symptoms","ru":"Описать симптомы"},{"id":"other_meds","ru":"Ответить про другие лекарства и аллергию"},{"id":"dosage","ru":"Уточнить, как и сколько принимать"}]', 110),
 ('no-legevakt', 'no', 'B2', 'health', 'Звонок в легевакт ночью',
  'A phone call to legevakten late in the evening: the learner''s adult daughter has had a high fever since the morning and now a bad headache. The nurse asks short triage questions (temperature, how long, other symptoms, medicines taken) and then gives advice: come in now, or wait and call again if it gets worse. Speak calmly but at natural speed.',
  'Erik, nurse at legevakten, calm and quick',
  '[{"id":"who","ru":"Сказать, кто болеет и что случилось"},{"id":"answer","ru":"Ответить на вопросы медсестры"},{"id":"advice","ru":"Понять совет и что делать дальше"},{"id":"repeat","ru":"Переспросить важное, если непонятно"}]', 120),
 ('no-fastlege', 'no', 'B2', 'health', 'На приёме у врача: боль в спине',
  'An appointment with the GP (fastlege). The learner has had lower back pain for two weeks after lifting at work. The doctor asks where it hurts, when it started, what makes it better or worse, then examines and suggests exercises, painkillers and maybe a few days of sick leave (sykemelding). The learner should ask about sick leave herself if the doctor does not mention it.',
  'Dr. Nilsen, fastlege, friendly and thorough',
  '[{"id":"describe","ru":"Описать боль: где, когда, от чего"},{"id":"answer","ru":"Ответить на вопросы врача"},{"id":"sick_leave","ru":"Спросить про больничный (sykemelding)"},{"id":"plan","ru":"Повторить своими словами, что делать"}]', 130),
 ('no-dentist', 'no', 'B1', 'health', 'Записаться к стоматологу',
  'A phone call to a dental clinic (tannlegekontor). The learner has had toothache for a few days. The secretary first offers a time in two weeks; only if the learner explains that it hurts a lot does she find an emergency slot tomorrow. The learner also asks what a check-up costs.',
  'Sara, tannhelsesekretær, efficient but friendly',
  '[{"id":"problem","ru":"Объяснить проблему с зубом"},{"id":"sooner","ru":"Добиться приёма пораньше"},{"id":"price","ru":"Спросить о цене"}]', 140),
-- ---------- Norwegian: work ----------
 ('no-interview-shop', 'no', 'B2', 'work', 'Собеседование: подработка в магазине',
  'A job interview for a part-time job (deltidsstilling) at a grocery store like Kiwi. The store manager asks the learner to present herself, about earlier work experience, which days she can work (evenings and weekends matter), how she would handle a stressed customer, and whether she has questions. Be realistic: friendly but a real interview.',
  'Lars, butikksjef, direct and friendly',
  '[{"id":"present","ru":"Рассказать о себе"},{"id":"experience","ru":"Рассказать об опыте работы"},{"id":"availability","ru":"Договориться о сменах"},{"id":"question","ru":"Задать свой вопрос о работе"}]', 210),
 ('no-interview-care', 'no', 'B2', 'work', 'Собеседование: помощник в доме престарелых',
  'A job interview for an assistant position at a nursing home (sykehjem). The ward manager asks why the learner wants to work in care (omsorg), about experience with elderly people, how she would act if a resident is confused and upset, and about her Norwegian (writing reports). The learner should also ask about training (opplæring) or courses towards helsefagarbeider.',
  'Anne, avdelingsleder at the sykehjem, warm but demanding',
  '[{"id":"motivation","ru":"Объяснить, почему хотите работать в уходе"},{"id":"situation","ru":"Рассказать, как поступите в трудной ситуации"},{"id":"language","ru":"Честно рассказать о своём норвежском"},{"id":"training","ru":"Спросить про обучение"}]', 220),
 ('no-first-day', 'no', 'B1', 'work', 'Первый день на новой работе',
  'The first day at a new job. A colleague shows the learner around: the break room, the coffee machine, the time sheet (timeliste) and who to ask about shifts. The learner asks about routines and introduces herself to the team.',
  'Kristin, colleague, cheerful and talkative',
  '[{"id":"introduce","ru":"Представиться коллеге"},{"id":"routines","ru":"Спросить о распорядке и перерывах"},{"id":"who_ask","ru":"Узнать, к кому обращаться со сменами"}]', 230),
 ('no-sick-call', 'no', 'B1', 'work', 'Позвонить начальнику: заболела',
  'A morning phone call to the boss: the learner is ill and cannot come to her shift today. The boss asks how long she will be away, reminds her about egenmelding, and asks if she can swap her Saturday shift with a colleague.',
  'Tor, the boss, understanding but busy',
  '[{"id":"tell","ru":"Сказать, что заболели и не придёте"},{"id":"how_long","ru":"Сказать, сколько примерно будете болеть"},{"id":"shift","ru":"Договориться о смене в субботу"}]', 240),
 ('no-customer', 'no', 'B2', 'work', 'На работе: покупатель с жалобой',
  'Role reversal: the learner works at an electronics shop like Expert, and the AI is an annoyed customer whose new kettle stopped working after one week. He wants his money back today. The learner must stay polite, ask for the receipt, explain the options (repair under warranty/reklamasjon, exchange) and calm him down.',
  'Per, an irritated customer in his sixties',
  '[{"id":"listen","ru":"Выслушать и вежливо ответить"},{"id":"receipt","ru":"Попросить чек"},{"id":"options","ru":"Объяснить варианты: ремонт или обмен"},{"id":"calm","ru":"Успокоить покупателя и договориться"}]', 250),
 ('no-volunteer', 'no', 'B1', 'work', 'Записаться волонтёром',
  'A phone call to the local volunteer centre (frivilligsentral). The learner would like to help, for example visiting elderly people or helping at a café for seniors. The coordinator asks what she likes to do, how often she can come and whether she has a police certificate (politiattest) — and explains how to get one.',
  'Bente, coordinator at the frivilligsentral, enthusiastic',
  '[{"id":"offer","ru":"Рассказать, чем хотите помогать"},{"id":"when","ru":"Сказать, когда можете приходить"},{"id":"attest","ru":"Понять, что такое politiattest и как его получить"}]', 260),
-- ---------- Norwegian: home and services ----------
 ('no-landlord', 'no', 'B1', 'home', 'Сломалась стиральная машина',
  'A phone call to the landlord (utleier): the washing machine in the flat has stopped working and there is water on the floor. The landlord first suggests the learner calls a repairman herself; the learner asks who pays, and they agree on a time when the repairman can come in.',
  'Geir, the landlord, a bit reluctant at first',
  '[{"id":"problem","ru":"Объяснить, что случилось"},{"id":"who_pays","ru":"Выяснить, кто платит за ремонт"},{"id":"time","ru":"Договориться, когда придёт мастер"}]', 310),
 ('no-visning', 'no', 'B2', 'home', 'Просмотр квартиры (visning)',
  'At a flat viewing (visning). The learner asks about the rent, the deposit (depositum), what is included (strøm, internet, parking), the neighbourhood and when the flat is free. Many people are interested, so at the end the owner asks her to tell a little about herself and why she would be a good tenant.',
  'Siri, the owner of the flat, friendly and businesslike',
  '[{"id":"costs","ru":"Спросить о цене и что входит"},{"id":"area","ru":"Спросить о районе и соседях"},{"id":"move_in","ru":"Узнать, когда можно въехать"},{"id":"present","ru":"Рассказать о себе как о жильце"}]', 320),
 ('no-dinner', 'no', 'B1', 'home', 'Приглашение на ужин',
  'A Norwegian friend calls to invite the learner to dinner on Saturday. The learner accepts, asks what to bring, mentions what she does not eat, and they talk a little about Norwegian and Ukrainian food traditions.',
  'Tone, a Norwegian friend, warm and curious',
  '[{"id":"accept","ru":"Принять приглашение"},{"id":"bring","ru":"Спросить, что принести"},{"id":"food","ru":"Рассказать о своей кухне и что не едите"}]', 330),
 ('no-nav', 'no', 'B2', 'services', 'Встреча в NAV',
  'A meeting with an adviser at NAV about finding work. The adviser asks about the learner''s education and work experience from Ukraine, what kind of job she wants in Norway, her Norwegian course, and suggests a work training place (arbeidstrening) or a course. The learner explains her wishes and asks what happens next.',
  'Ahmed, veileder at NAV, patient and practical',
  '[{"id":"background","ru":"Рассказать об образовании и опыте"},{"id":"wish","ru":"Объяснить, какую работу хотите"},{"id":"offer","ru":"Понять предложение консультанта"},{"id":"next","ru":"Спросить о следующих шагах"}]', 410),
 ('no-bank', 'no', 'B1', 'services', 'В банке: BankID и карта',
  'At the bank. The learner wants to get BankID and a new bank card. The adviser explains what papers are needed (passport or ID card, residence permit) and that BankID on the phone comes after; the learner forgot one document and must agree to come back.',
  'Camilla, bank adviser, polite and precise',
  '[{"id":"want","ru":"Объяснить, что вам нужно"},{"id":"papers","ru":"Понять, какие документы нужны"},{"id":"again","ru":"Договориться прийти ещё раз"}]', 420),
 ('no-parcel', 'no', 'B1', 'services', 'Посылка не пришла',
  'At a parcel pickup point (hentested) in a grocery store. The learner got a message that a parcel arrived, but the clerk cannot find it. They check the tracking number and ID; it turns out the parcel was sent to another pickup point nearby.',
  'Even, a young store clerk',
  '[{"id":"explain","ru":"Объяснить, за чем пришли"},{"id":"details","ru":"Назвать номер посылки и показать документ"},{"id":"where","ru":"Понять, где посылка"}]', 430),
 ('no-bus', 'no', 'B1', 'services', 'Автобус задерживается',
  'At a bus stop. The bus is very late, and the learner has an appointment soon. She asks another passenger whether the bus has been cancelled, how to buy a ticket in the Ruter app or on board, and which other bus or tram she can take.',
  'Ola, a student waiting at the same stop',
  '[{"id":"ask","ru":"Спросить про автобус"},{"id":"ticket","ru":"Узнать, как купить билет"},{"id":"other_way","ru":"Найти другой путь"}]', 440),
 ('no-hairdresser', 'no', 'B1', 'services', 'В парикмахерской',
  'At a hairdresser. The learner explains how she wants her hair (shorter, keep the length at the back, maybe colour), asks about the price, and books the next appointment. The hairdresser makes small talk about the weekend.',
  'Lene, frisør, chatty',
  '[{"id":"wish","ru":"Объяснить, какую стрижку хотите"},{"id":"price","ru":"Спросить о цене"},{"id":"next","ru":"Записаться в следующий раз"}]', 450),
