  '[{"id":"symptoms","ru":"Описать, что болит"},{"id":"medicine","ru":"Попросить лекарство"},{"id":"dosage","ru":"Понять, как принимать"}]', 200),
 ('en-phone-booking', 'en', 'A2', 'services', 'Забронировать столик по телефону',
